BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

ALTER TABLE catalogo.area ADD CONSTRAINT ck_area_padre CHECK ((padre_id <> id));
ALTER TABLE catalogo.categoria_incidencia ADD CONSTRAINT ck_categoria_incidencia_plazo CHECK ((plazo_dias_habiles > 0));
ALTER TABLE catalogo.establecimiento_salud ADD CONSTRAINT ck_establecimiento_salud_renipress CHECK ((codigo_renipress ~ '^[1-9][0-9]{0,7}$'::text));
ALTER TABLE catalogo.etiqueta ADD CONSTRAINT ck_etiqueta_descripcion CHECK (((descripcion IS NULL) OR (char_length(descripcion) <= 200)));
ALTER TABLE catalogo.etiqueta ADD CONSTRAINT ck_etiqueta_nombre CHECK (((nombre = btrim(nombre)) AND ((char_length(nombre) >= 2) AND (char_length(nombre) <= 40))));
ALTER TABLE catalogo.etiqueta ADD CONSTRAINT ck_etiqueta_tono CHECK ((tono = ANY (ARRAY['neutral'::text, 'primary'::text, 'success'::text, 'warning'::text, 'danger'::text])));
ALTER TABLE chatbot.archivo_recibido ADD CONSTRAINT ck_archivo_recibido_cierre CHECK (((estado_archivo_id = ANY (ARRAY[3, 4])) = (verificado_en IS NOT NULL)));
ALTER TABLE chatbot.archivo_recibido ADD CONSTRAINT ck_archivo_recibido_rechazo CHECK (((estado_archivo_id = 4) = (motivo_rechazo IS NOT NULL)));
ALTER TABLE chatbot.archivo_recibido ADD CONSTRAINT ck_archivo_recibido_tamano CHECK ((tamano > 0));
ALTER TABLE chatbot.archivo_recibido ADD CONSTRAINT ck_archivo_recibido_verificado CHECK (((estado_archivo_id <> 3) OR ((mime_detectado IS NOT NULL) AND (hash_archivo IS NOT NULL))));
ALTER TABLE chatbot.contador_codigo_incidencia ADD CONSTRAINT ck_contador_codigo_incidencia_anio CHECK (((anio >= 1000) AND (anio <= 9999)));
ALTER TABLE chatbot.contador_codigo_incidencia ADD CONSTRAINT ck_contador_codigo_incidencia_ultimo CHECK ((ultimo >= 0));
ALTER TABLE chatbot.evidencia ADD CONSTRAINT ck_evidencia_tamano CHECK ((tamano > 0));
ALTER TABLE chatbot.incidencia_etiqueta ADD CONSTRAINT ck_incidencia_etiqueta_eliminacion CHECK (((activo AND (eliminado_en IS NULL) AND (eliminado_por IS NULL)) OR ((NOT activo) AND (eliminado_en IS NOT NULL) AND (eliminado_por IS NOT NULL))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_anonimo CHECK (((NOT es_anonimo) OR ((dni_reclamante IS NULL) AND (nombre_reclamante IS NULL))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_archivo CHECK (((archivado_en IS NULL) = (motivo_archivo_id IS NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_archivo_detalle CHECK (((archivo_detalle IS NULL) OR ((motivo_archivo_id IS NOT NULL) AND (char_length(btrim(archivo_detalle)) >= 10))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_archivo_manual CHECK (((motivo_archivo_id IS NULL) OR (motivo_archivo_id <> ALL (ARRAY[3, 4])) OR (archivo_detalle IS NOT NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_codigo CHECK ((codigo ~ '^MINSA-[0-9]{4}-[0-9]{6,}$'::text));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_confianza CHECK (((categoria_confianza IS NULL) OR ((categoria_confianza >= (0)::numeric) AND (categoria_confianza <= (100)::numeric))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_derivacion CHECK (((derivado_en IS NULL) = (derivado_por IS NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_derivacion_descripcion CHECK (((derivacion_descripcion IS NULL) OR ((derivacion_descripcion = btrim(derivacion_descripcion)) AND ((char_length(derivacion_descripcion) >= 10) AND (char_length(derivacion_descripcion) <= 2000)))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_eliminacion CHECK (((activo AND (eliminado_en IS NULL) AND (eliminado_por IS NULL)) OR ((NOT activo) AND (eliminado_en IS NOT NULL) AND (eliminado_por IS NOT NULL))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_estado CHECK (((estado_incidencia_id = ANY (ARRAY[1, 4, 5, 7])) OR (categoria_ia_id IS NOT NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_motivo_archivo CHECK (((estado_incidencia_id = 7) = (motivo_archivo_id IS NOT NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_reapertura CHECK ((((reabierto_en IS NULL) = (reabierto_por IS NULL)) AND ((reabierto_en IS NULL) = (reabierto_motivo IS NULL)) AND ((reabierto_motivo IS NULL) OR (char_length(btrim(reabierto_motivo)) >= 10))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_resolucion CHECK ((((medidas_tomadas IS NULL) = (resuelto_en IS NULL)) AND ((medidas_tomadas IS NULL) = (resuelto_por IS NULL)) AND ((medidas_tomadas IS NULL) = (fundamento IS NULL)) AND ((medidas_tomadas IS NULL) = (resultado_resolucion_id IS NULL)) AND ((medidas_tomadas IS NULL) OR ((char_length(btrim(medidas_tomadas)) >= 10) AND (char_length(btrim(fundamento)) >= 10)))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_resuelto CHECK (((estado_incidencia_id <> 4) OR (medidas_tomadas IS NOT NULL)));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_revision CHECK ((((categoria_confirmada_en IS NULL) = (categoria_confirmada_por IS NULL)) AND ((categoria_confirmada_en IS NULL) OR (categoria_corregida_en IS NULL))));
ALTER TABLE chatbot.incidencia_paciente ADD CONSTRAINT ck_incidencia_paciente_toma CHECK (((tomado_en IS NULL) = (tomado_por IS NULL)));
ALTER TABLE chatbot.incidencia_paciente_auditoria ADD CONSTRAINT ck_incidencia_paciente_auditoria_operacion CHECK (((operacion)::text = ANY ((ARRAY['CREACION'::character varying, 'ACTUALIZACION'::character varying])::text[])));
ALTER TABLE chatbot.solicitud_carga ADD CONSTRAINT ck_solicitud_carga_destino CHECK (((incidencia_paciente_id IS NOT NULL) OR (sesion_id IS NOT NULL)));
ALTER TABLE chatbot.solicitud_carga ADD CONSTRAINT ck_solicitud_carga_limites CHECK (((max_archivos > 0) AND (max_bytes_archivo > 0)));
ALTER TABLE chatbot.solicitud_carga ADD CONSTRAINT ck_solicitud_carga_vencimiento CHECK ((vence_en > fecha_creacion));
ALTER TABLE chatbot.usuario ADD CONSTRAINT ck_usuario_eliminacion CHECK (((activo AND (eliminado_en IS NULL) AND (eliminado_por IS NULL)) OR ((NOT activo) AND (eliminado_en IS NOT NULL) AND (eliminado_por IS NOT NULL))));
ALTER TABLE gestion.usuario_interno ADD CONSTRAINT ck_usuario_interno_correo_minusculas CHECK ((correo = lower(correo)));
ALTER TABLE gestion.usuario_interno ADD CONSTRAINT ck_usuario_interno_eliminacion CHECK (((activo AND (eliminado_en IS NULL) AND (eliminado_por IS NULL)) OR ((NOT activo) AND (eliminado_en IS NOT NULL) AND (eliminado_por IS NOT NULL))));
ALTER TABLE gestion.usuario_interno ADD CONSTRAINT ck_usuario_interno_password_hash CHECK (starts_with(password_hash, '$argon2id$'::text));

CREATE UNIQUE INDEX uq_etiqueta_nombre ON catalogo.etiqueta USING btree (lower(nombre));
CREATE INDEX ix_archivo_recibido_pendiente ON chatbot.archivo_recibido USING btree (fecha_creacion) WHERE (estado_archivo_id = ANY (ARRAY[1, 2]));
CREATE INDEX ix_incidencia_etiqueta_etiqueta_activa ON chatbot.incidencia_etiqueta USING btree (etiqueta_id, incidencia_paciente_id) WHERE activo;
CREATE UNIQUE INDEX uq_incidencia_etiqueta_activa ON chatbot.incidencia_etiqueta USING btree (incidencia_paciente_id, etiqueta_id) WHERE activo;
CREATE INDEX ix_incidencia_paciente_abierta ON chatbot.incidencia_paciente USING btree (area_destino_id, fecha_creacion) WHERE (activo AND (estado_incidencia_id = ANY (ARRAY[1, 2, 3, 6])));
CREATE INDEX ix_incidencia_paciente_cursor ON chatbot.incidencia_paciente USING btree (fecha_creacion DESC, id DESC) WHERE activo;
CREATE INDEX ix_incidencia_paciente_destino_cursor ON chatbot.incidencia_paciente USING btree (area_destino_id, fecha_creacion DESC, id DESC) WHERE activo;
CREATE INDEX ix_incidencia_paciente_destino_estado_fecha ON chatbot.incidencia_paciente USING btree (area_destino_id, estado_incidencia_id, fecha_creacion DESC) INCLUDE (categoria_id) WHERE activo;
CREATE INDEX ix_incidencia_paciente_pendiente_ia ON chatbot.incidencia_paciente USING btree (fecha_creacion) WHERE ((categoria_ia_id IS NULL) AND activo);
CREATE INDEX ix_incidencia_paciente_pendiente_revision ON chatbot.incidencia_paciente USING btree (categoria_confianza, fecha_creacion) WHERE ((categoria_ia_id IS NOT NULL) AND (categoria_corregida_en IS NULL) AND (categoria_confirmada_en IS NULL) AND activo);
CREATE INDEX ix_mensaje_fallido ON chatbot.mensaje USING btree (usuario_id, fecha_hora) WHERE (estado_mensaje_id = 5);
CREATE INDEX ix_solicitud_carga_abierta ON chatbot.solicitud_carga USING btree (vence_en) WHERE (cerrada_en IS NULL);
CREATE INDEX ix_solicitud_carga_sesion_sin_incidencia ON chatbot.solicitud_carga USING btree (sesion_id) WHERE ((incidencia_paciente_id IS NULL) AND (cerrada_en IS NULL));

COMMIT;
